import {chapterConnectionsPage,bindChapterConnections,resetChapterConnections} from './chapter-connections-ui.mjs';
import {freedomDocumentsSource} from './freedom-documents-content.mjs';
import {resetTwoThreads,twoThreadsPage,bindTwoThreads,threadsEnglishInvitation} from './two-threads-ui.mjs';
import {evidenceStories,evidenceChallenges,evidenceReaders} from './evidence-voice-stories.mjs';
import {evidenceVoiceSource} from './evidence-voice-content.mjs';
import {stormAccountsSource} from './storm-accounts-content.mjs';
import {evidenceVoiceView,startEvidenceVoice,setEvidenceLesson,setEvidenceText,annotateEvidence,answerEvidence,supportEvidence,exposeEvidence,skipEvidence,setEvidenceReading,keepEvidence,setEvidenceAnnotationDraft,evidenceStorySuggestion,createEvidenceStory,removableEvidenceStories,removeEvidenceStory,validEvidenceVisit,evidenceSeenStories,validEvidenceUnit} from './evidence-voice-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const labels={interpretation:'My first interpretation',comparison:'My comparison of the accounts',reconsideration:'What I would change or retain, and why',claim:'My claim (optional planning)',detail:'A precise detail or passage (optional planning)',reasoning:'Why the detail supports my claim (optional planning)',paragraph:'My own paragraph for the reader',objection:'A fair objection in my own words',revision:'My revised paragraph for the reader',change:'What I changed or kept, and why (optional)'};
let leaveGuard,threadMode=null,chapterMode=null,threadReturn=null,threadParentBinding=null,threadParentCleanup=null,pendingEvidenceNavigation=()=>false;
export const guardEvidenceNavigation=()=>pendingEvidenceNavigation();
export function resetEvidenceVoiceModes(){leaveGuard?.abort();threadParentCleanup?.();pendingEvidenceNavigation=()=>false;threadMode=null;chapterMode=null;threadReturn=null;threadParentBinding=null;resetTwoThreads();resetChapterConnections();}
function chaptersActive(book,owner){if(chapterMode&&location.hash!=='#learn/english')chapterMode=null;return !!chapterMode&&chapterMode.book===book&&chapterMode.owner===owner&&location.hash==='#learn/english';}
function threadsActive(book,owner){if(threadMode&&location.hash!=='#learn/english')threadMode=null;return !!threadMode&&threadMode.book===book&&threadMode.owner===owner&&location.hash==='#learn/english';}
function returnView(book,owner){if(!threadReturn||threadReturn.book!==book||threadReturn.owner!==owner)threadReturn={book,owner,open:false};return threadReturn;}
const audio=(text,label)=>`<span data-ev-audio>${hearButton(text,label,'en')}</span>`;
export const evidenceVoiceEntry=()=>'<aside class="ev-entry"><h2>Evidence & voice</h2><p>Read a complete story, reconsider its narrators, and keep an argument for another reader.</p><a class="secondary" href="#learn/english">Open English</a><a class="secondary" href="#learn/english/storm-records">Compare storm records</a></aside>';
const historicalLabels={comparison:'My explanation of the petition',reconsideration:'My comparison and remaining question'};
const fieldLabel=(source,key)=>source.kind==='historical-pair'?(historicalLabels[key]||labels[key]||key):(labels[key]||key);
function paragraphLabel(p,historical=false){if(!historical)return typeof p.label==='string'?p.label:p.id;return Object.hasOwn(p,'label')&&typeof p.label==='string'&&p.label.trim()&&[...p.label].length<=200?p.label:'Passage '+p.id;}
function chapter(c,full=false,historical=false){return `<section class="ev-chapter"><h3>${esc(c.title)}</h3>${audio(c.paragraphs.map(p=>historical?paragraphLabel(p,true)+'. '+p.text:p.text).join('\n\n'),`Hear ${c.title}`)}${c.paragraphs.map(p=>`<div class="ev-passage ${historical&&p.primary===true?'ev-primary':''}" id="ev-${full?'whole':'stage'}-${esc(p.id)}"><p class="ev-anchor">${esc(paragraphLabel(p,historical))}</p><p>${esc(p.text)}</p>${btn(`data-ev-anchor="${esc(p.id)}"`,'Choose this passage for a note')}</div>`).join('')}</section>`;}
function whole(source){return `<details class="ev-whole" data-ev-whole><summary>${source.kind==='historical-pair'?'All saved source excerpts':source.kind==='account-pair'?'All saved source documents':`The complete story · all ${source.chapters.length} chapters`}</summary><p>${esc(source.notice)}</p>${source.chapters.map(c=>chapter(c,true,source.kind==='historical-pair')).join('')}</details>`;}
function keptBody(k){if(!k)return '<p>Not kept yet.</p>';const fields=k.kind==='revision'?['objection','revision','change']:['claim','detail','reasoning','paragraph'];const written=fields.filter(field=>(k.drafts[field]??'')!=='');return written.length?fields.map(field=>`<section><h4>${esc(fieldLabel(k.source,field))}</h4><p class="ev-own">${k.drafts[field]===undefined||k.drafts[field]===''?'No words added in this field.':esc(k.drafts[field])}</p></section>`).join(''):'<p class="ev-own">Kept blank — no words added.</p>';}
function snapshots(w){return `<details class="ev-versions"><summary>Read my kept versions</summary>${[['firstDraft','First kept draft'],['firstRevision','First kept revision'],['kept','Latest kept reader-facing piece']].map(([k,label])=>`<section data-ev-version="${k}"><h3>${label}</h3>${keptBody(w[k])}</section>`).join('')}</details>`;}

function annotations(w){const d=w.annotationDraft??{anchor:'',kind:'inference',text:''},ps=w.source.chapters.flatMap(c=>c.paragraphs);return `<section class="ev-annotation"><h3>Annotate an exact passage</h3><p>Choose a paragraph, label your note, and keep your own words. Labels are your choices; notes are ungraded.</p><label>Passage<select data-ev-note-anchor><option value="">Choose a passage</option>${ps.map(p=>`<option value="${esc(p.id)}" ${d.anchor===p.id?'selected':''}>${esc(paragraphLabel(p,w.source.kind==='historical-pair'))} · ${esc(p.text.slice(0,70))}…</option>`).join('')}</select></label><p class="ev-note-preview">${esc(ps.find(p=>p.id===d.anchor)?.text||'The chosen exact paragraph will appear here.')}</p><label>My note is a<select data-ev-note-kind>${[['literal','Literal detail'],['inference','My inference'],['question','My question']].map(([v,l])=>`<option value="${v}" ${d.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label>My annotation<textarea data-ev-note-text rows="3">
${esc(d.text)}</textarea></label>${btn('data-ev-note-keep','Keep this annotation')}<details><summary>My kept annotations (${w.annotations.length})</summary>${w.annotations.map(a=>`<article class="ev-kept-note"><h4>${esc(a.anchor)} · ${esc(a.kind)}</h4><blockquote>${esc(a.passage)}</blockquote><p class="ev-own">${esc(a.text||'Kept blank — no words added.')}</p></article>`).join('')||'<p>No kept annotations yet.</p>'}</details></section>`;}
function questions(w,l){return w.source.questions.filter(q=>q.lesson===l.id).map(q=>{const last=w.responses.filter(r=>r.question.id===q.id).at(-1);return `<fieldset class="ev-question"><legend>${esc(q.prompt)}</legend><div class="ev-choices">${q.choices.map(c=>btn(`data-ev-answer="${esc(q.id)}:${esc(c.id)}" aria-pressed="${last?.choice===c.id}"`,c.label)).join('')}</div>${last?`<p class="ev-feedback" id="ev-feedback-${esc(q.id)}" tabindex="-1"><strong>Last structured check:</strong> ${esc(last.feedback)}</p>`:''}</fieldset>`;}).join('');}
function lesson(w,l){const support=w.support[l.id]??[];return `${validEvidenceVisit(w.visit)?`<p class="ev-visit">${w.visit.familiarity==='rereading'?'Rereading a familiar story':'A new story for this notebook'} · ${esc(evidenceChallenges.find(c=>c.id===w.visit.challenge)?.title??'Saved challenge')} · ${esc(w.source.reader?.title??'Saved reader')}</p>`:''}<h2 id="ev-heading" tabindex="-1">${esc(l.title)}</h2><p>${esc(l.prompt)}</p><aside class="ev-support"><h3>Choose any help</h3><div class="ev-actions">${[['learn','Learn'],['guided','Guided walkthrough'],['hint','Hint'],['example','Different example'],['together','We’re working together']].map(([k,t])=>btn(`data-ev-support="${k}" aria-pressed="${support.includes(k)}"`,t)).join('')}</div>${['learn','guided','hint','example'].filter(k=>support.includes(k)).map(k=>`<section><h4>${{learn:'Learn',guided:'Guided walkthrough',hint:'Hint',example:'Different example'}[k]}</h4><p>${esc(l[k])}</p>${audio(l[k],`Hear ${k==='guided'?'the walkthrough':k==='example'?'the different example':k}`)}</section>`).join('')}${support.includes('together')?'<p>Working together is recorded separately from the structured responses.</p>':''}</aside>${l.id==='revise'?`<aside class="ev-earlier"><h3>Your first kept draft</h3>${w.firstDraft?keptBody(w.firstDraft):`<p>No first draft has been kept. You can write a revision directly, or visit ${esc(w.source.kind==='historical-pair'?(w.source.lessons.find(x=>x.id==='write')?.title||'Write for a reader'):'Write for a reader')}.</p>`}</aside>`:''}<div class="ev-reading">${w.source.chapters.filter(c=>l.chapters.includes(c.id)).map(c=>chapter(c,false,w.source.kind==='historical-pair')).join('')}</div>${l.id==='later'&&!['account-pair','historical-pair'].includes(w.source.kind)?`<aside class="ev-revisit"><h3>Return to the earlier interpretation</h3>${(Array.isArray(w.source.revisit)?w.source.revisit:['c1-p3','c3-p1','c3-p2']).map(id=>{const p=w.source.chapters.flatMap(c=>c.paragraphs).find(p=>p.id===id);return p?`<p><strong>${esc(id)}</strong> ${esc(p.text)}</p>`:'';}).join('')}<h4>Your first interpretation</h4><p class="ev-own">${esc(w.drafts.interpretation||'No earlier words were added. You can reconsider the narrated suspicion itself.')}</p></aside>`:''}${questions(w,l)}${annotations(w)}<section class="ev-writing"><h3>Your words for a reader</h3><p>These fields are ungraded. You can write, dictate to someone beside you, or discuss aloud. No text is sent anywhere. Each field holds up to 8,000 characters.</p>${l.fields.map(k=>`<label>${esc(fieldLabel(w.source,k))}<textarea rows="${['paragraph','revision'].includes(k)?7:3}" data-ev-field="${esc(k)}">
${esc(w.drafts[k]??'')}</textarea></label>`).join('')}${['write','revise'].includes(l.id)?btn(`data-ev-keep="${l.id==='write'?'draft':'revision'}"`,l.id==='write'?'Keep my first draft / latest draft':'Keep my revision for the reader',true):''}${l.id==='revise'?'<p>Human review: What claim did the reader understand? Which detail supported it? Did the objection help you clarify or narrow it?</p>':''}${snapshots(w)}</section><details><summary>Reading report · kept until changed</summary><p>This report applies to later checks until you change it. A report is separate from an assessment of independent reading.</p><div class="ev-actions">${[['unobserved','Reading not observed'],['together','Read together'],['reported-independent','Reported read independently']].map(([v,t])=>btn(`data-ev-reading="${v}" aria-pressed="${w.reading===v}"`,t)).join('')}</div></details><div class="ev-actions">${btn('data-ev-skip',w.skipped.includes(l.id)?'This lesson is marked skipped':'Skip this lesson for now')}<a class="secondary" href="#learn/english">English sequence</a></div>`;}
function explorationControls(state){const suggestion=evidenceStorySuggestion(state),removable=removableEvidenceStories(state),seen=evidenceSeenStories(state);return `<section class="ev-exploration"><h2 tabindex="-1">Read another story</h2><p>${esc(suggestion.reason)}</p><p>Four complete original stories. Change the story, the thinking challenge, or your reader. Every option is open; repeated texts are rereading.</p>${suggestion.available?`<label>Story<select data-ev-story>${evidenceStories.map(s=>`<option value="${s.id}" ${suggestion.story===s.id?'selected':''}>${esc(s.title)}${seen.includes(s.id)?' · rereading':''}</option>`).join('')}</select></label><label>Thinking challenge<select data-ev-challenge>${evidenceChallenges.map(c=>`<option value="${c.id}" ${suggestion.challenge===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Reader<select data-ev-reader>${evidenceReaders.map(r=>`<option value="${r.id}" ${suggestion.reader===r.id?'selected':''}>${esc(r.title)}</option>`).join('')}</select></label>${btn('data-ev-create','Create this story visit',true)}`:'<p>New-copy selection is unavailable because optional saved selection metadata cannot be read. Your existing stories are still open.</p>'}<p><a class="secondary" href="#notes">Open notes to download this notebook</a></p>${removable.length?`<details class="ev-removal"><summary>Make space by choosing a generated visit</summary><p>Fixed stories and retained unreadable records are protected. Nothing is removed automatically.</p><label>Generated visit<select data-ev-remove-choice><option value="">Choose a copy</option>${removable.map(u=>`<option value="${esc(u.id)}">${esc(u.title)} · ${esc(u.id)}</option>`).join('')}</select></label>${btn('data-ev-remove-review','Review this removal')}<div data-ev-remove-warning></div></details>`:''}</section>`;}
// A source picture introduces the documents; it adds no event evidence.
function sourcePicture(){return `<figure class="ev-source-picture"><svg viewBox="0 0 480 130" aria-hidden="true" focusable="false"><g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M45 105h125M60 105V20h94v85M107 20v85M60 62h94"/><path d="M183 104h28M190 104V79h14v25M197 79V67"/><path d="M177 65q20-30 40 0z" fill="#e6bc64"/><path d="M312 100V29h89v71zM326 45h61M326 60h61M326 75h42M303 108h110"/><path d="M297 20h89v9M289 12h89v8"/></g></svg><figcaption>One view at a window. Reports gathered into a notice.</figcaption></figure>`;}
export function evidenceVoicePage(state,requestedLesson,owner){
 if(chaptersActive(state,owner))return chapterConnectionsPage(state,owner);if(threadsActive(state,owner))return twoThreadsPage(state,owner);const returning=returnView(state,owner);
 const v=evidenceVoiceView(state),accountEntry=requestedLesson==='storm-records',historicalEntry=requestedLesson==='freedom-documents';
 const fixed=state.evidenceVoice?.units?.[historicalEntry?'freedom-documents':'storm-accounts'];
 const historicalUnreadable=historicalEntry&&Object.hasOwn(state.evidenceVoice?.units??{},'freedom-documents')&&!validEvidenceUnit(fixed);
 const historicalPreview=historicalEntry&&(!v.work||state.evidenceVoice.current!=='freedom-documents');
 const accountPreview=accountEntry&&(!v.work||state.evidenceVoice.current!=='storm-accounts');
 const w=accountPreview||historicalPreview?null:v.work,source=historicalPreview?(validEvidenceUnit(fixed)?fixed.source:freedomDocumentsSource):accountPreview?(validEvidenceUnit(fixed)?fixed.source:stormAccountsSource):(w?.source??evidenceVoiceSource);
 const historical=source.kind==='historical-pair',accounts=source.kind==='account-pair',requested=source.lessons.find(l=>l.id===requestedLesson),preview=requested&&(!w||w.lesson!==requested.id);
 const units=v.units.filter(u=>u.readable);
 const copyId=(()=>{let n=1,id='clock-river';while(Object.hasOwn(state.evidenceVoice?.units??{},id))id=`clock-river-copy-${n++}`;return id;})();
 const startKey=historicalPreview?'freedom-documents':accountPreview?'storm-accounts':w?state.evidenceVoice.current:(!Object.hasOwn(state.evidenceVoice?.units??{},'clock-river')?'clock-river':copyId);
 const accountLesson=validEvidenceUnit(fixed)?fixed.lesson:source.lessons[0].id;
 const heading=historical?'Freedom Documents':accounts?'Two records of storm night':'Evidence & voice';
 return `<div class="ev-page ${historical?'ev-historical-page':accounts?'ev-account-page':''}" data-ev-root ${accountPreview||historicalPreview?'data-ev-source-preview':''} lang="en"><header><a class="back" href="#pathways">Subjects</a><p>${historical?'Historical documents · reading and writing':`English · ${accounts?'read two sources':'reading and writing'}`}</p><h1>${heading}</h1>${historical?'<p>Read a claim, a petition, and the difference between a request and a result.</p>':''}${btn('data-ev-threads','Two Threads')}${btn('data-ev-chapter-map','The Chapter Map')}<p>${esc(source.title)}${historical?' — selected excerpts, not complete documents.':accounts?' — two short fictional records.':` — a complete original story in ${source.chapters.length} chapters.`} Choose any lesson; help is always available.</p><a class="secondary" href="#learn/english/storm-records">Compare storm records</a><a class="secondary" href="#learn/english/freedom-documents">Freedom Documents</a>${v.status!=='unavailable'&&!historicalUnreadable?btn('data-ev-more','Read another story'):''}</header>
 ${historicalUnreadable?`<h2 id="ev-heading" tabindex="-1">Earlier historical work is retained</h2><p>This earlier historical record cannot be edited here. Download Notes or choose another reading.</p><a class="secondary" href="#notes">Open notes</a><div class="ev-actions">${units.map(u=>btn(`data-ev-unit-open="${esc(u.id)}"`,u.title)).join('')}</div>`:v.status==='unavailable'?'<h2 id="ev-heading" tabindex="-1">Your earlier English record is retained</h2><p>This version cannot edit that format. It remains in notes downloads. Other subjects stay open.</p><a class="secondary" href="#notes">Open notes</a>':`
 <nav class="ev-lessons" aria-label="English lessons">${source.lessons.map((l,i)=>btn(`data-ev-open="${esc(l.id)}" data-ev-unit="${esc(startKey)}" aria-current="${w?.lesson===l.id&&!preview?'step':'false'}"`,`${i+1}. ${l.title}`)).join('')}</nav>
 ${units.length>1||(!w&&units.length>0)?`<details class="ev-copies"><summary>Saved stories and source work</summary>${units.map(u=>btn(`data-ev-unit-open="${esc(u.id)}" aria-pressed="${!!w&&state.evidenceVoice.current===u.id}"`,`${u.title} · ${u.id}${w&&state.evidenceVoice.current===u.id?' · current':''}`)).join('')}</details>`:''}
 ${v.units.some(u=>!u.readable)?'<p>An earlier unreadable story record is retained. Other readable sources and stories stay open.</p>':''}
 ${historicalPreview?`<section class="ev-preview"><h2 id="ev-heading" tabindex="-1">Open the document drawer</h2><p>${esc(source.notice)}</p><p>The librarian wants a careful explanation for a reader who has not seen these sources. Who made each document, who was being addressed, and what does each document ask us to believe or do?</p><p>Open a lesson to read, annotate or hear its excerpts. Every lesson is open.</p>${btn(`data-ev-open="${esc(accountLesson)}" data-ev-unit="freedom-documents"`,'Open Freedom Documents',true)}</section>`:accountPreview?`<section class="ev-preview"><h2 id="ev-heading" tabindex="-1">Read the town’s storm records</h2><p>${esc(source.notice)}</p>${sourcePicture()}<p>Compare what each writer knew, then keep a message for a visiting neighbor. You can read, listen or work together.</p><p>Open the storm records to hear them read aloud.</p>${btn(`data-ev-open="${esc(accountLesson)}" data-ev-unit="storm-accounts"`,'Open the storm records',true)}</section>`:preview?`<section class="ev-preview"><h2 id="ev-heading" tabindex="-1">${esc(requested.title)}</h2><p>${esc(requested.prompt)}</p><p>${esc(requested.learn)}</p>${btn(`data-ev-open="${esc(requested.id)}" data-ev-unit="${esc(startKey)}"`,'Start / continue this lesson',true)}</section>`:w?`${accounts?sourcePicture():''}${lesson(w,source.lessons.find(l=>l.id===w.lesson))}`:`<section class="ev-preview"><h2 id="ev-heading" tabindex="-1">A clock falls silent. Whose account should you trust?</h2><p>Follow five connected lessons: read, compare, reconsider, write, revise. Start with reading or choose the writing task directly. Nothing is locked.</p>${btn(`data-ev-open="before" data-ev-unit="${esc(startKey)}"`,'Begin with the first account',true)}</section>`}
 ${accountPreview||historicalPreview?'':whole(source)}${explorationControls(state)}`}
 ${threadsEnglishInvitation(state,{open:returning.open})}<p id="ev-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a class="secondary" href="#notes">Grown-up notes</a><a class="secondary" href="#pathways">Other subjects</a></footer></div>`;
}
export function evidenceVoiceNotes(state){if(!Object.hasOwn(state,'evidenceVoice'))return '';const v=evidenceVoiceView(state);return `<details class="panel ev-notes"><summary>English · Evidence & voice</summary><p>Original complete stories and a short fictional storm-record comparison. Selected historical excerpts can be kept alongside original stories and fictional storm records. Sources and writing stay separate; the app does not grade original historical arguments or establish course completion. Story challenges and readers stay open; storm checks are separate source-comparison practice. Own writing and annotation notes are human-read and ungraded. Structured checks, support before each attempt, skips, shown text and reading reports remain separate. Visits and kept drafts do not establish course completion or independent reading.</p>${v.units.filter(u=>u.readable).map(u=>{const w=state.evidenceVoice.units[u.id];return `<h3>${esc(u.title)} · ${esc(u.id)}</h3>${validEvidenceVisit(w.visit)?`<p>${w.visit.familiarity==='rereading'?'Rereading':'New text'} · challenge ${esc(w.visit.challenge)} · ${esc(w.source.reader?.title??w.visit.reader)}</p>`:''}<p>${w.responses.length} structured attempts; ${w.annotations.length} kept annotations.</p>${snapshots(w)}`;}).join('')}<details><summary>Exact saved material and work (including retained formats)</summary><pre>${esc(JSON.stringify(state.evidenceVoice,null,2))}</pre></details></details>`;}
export function bindEvidenceVoice(state,ctx={}){
 ctx=ctx||{};const {save,render,focus,canExport,explorerId,isActive,entryLesson,notebook}=ctx;
 leaveGuard?.abort();threadParentCleanup?.();pendingEvidenceNavigation=()=>false;leaveGuard=new AbortController();threadParentBinding=null;
 if(chapterMode?.book===state&&chapterMode.owner===explorerId?.()&&location.hash==='#learn/english'){
  const captured=chapterMode;bindChapterConnections(state,{...ctx,backLabel:'Back to English',isChapterMapActive:()=>chapterMode===captured&&chapterMode.book===state&&chapterMode.owner===explorerId?.()&&location.hash==='#learn/english',onBack:()=>{if(chapterMode!==captured)return;chapterMode=null;history.replaceState(null,'',captured.parentRoute);render?.();focus?.('[data-ev-chapter-map]');}});return;
 }
 if(threadMode?.book===state&&location.hash==='#learn/english'){
  const captured=threadMode;bindTwoThreads(state,{...ctx,backLabel:'Back to English',isThreadsActive:()=>threadMode===captured&&threadMode.book===state&&threadMode.owner===explorerId?.()&&location.hash==='#learn/english',onBack:()=>{if(threadMode!==captured)return;threadMode=null;history.replaceState(null,'',captured.parentRoute);render?.();focus?.('[data-ev-threads]');}});return;
 }
 const root=document.querySelector('[data-ev-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport},dirty=new Set(),annotationDirty=Symbol('annotation');
 const live=el=>typeof notebook==='function'&&notebook()===state&&document.querySelector('[data-ev-root]')===root&&root.isConnected&&el.isConnected&&root.contains(el)&&el.getClientRects().length>0&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;
 const say=(text,take=false)=>{const n=root.querySelector('#ev-status');if(n){n.textContent=text;if(take)n.focus();}};
 const redraw=(message='',target='#ev-heading')=>{stopSpeech();save?.();render?.();const n=document.querySelector('#ev-status');if(n)n.textContent=message;focus?.(target);};
 const unsaved=(message='Your visible words have not been saved. Edit the indicated field to try again, or copy your words before restoring the last saved version.',take=true)=>{say(message,take);const status=root.querySelector('#ev-status'),b=document.createElement('button');b.type='button';b.className='secondary';b.dataset.evRestore='';b.textContent='Restore last saved words';b.addEventListener('click',()=>{if(!live(b)||!window.confirm('Discard the visible unsaved edits and restore this page’s last saved words? Earlier saved work stays unchanged.'))return;dirty.clear();redraw('Last saved words restored. Notes and story choices are available.');});status?.append(b);};
 bindThreadsParent(state,ctx,root,{owner,route,dirty,unsaved});
 const act=(el,fn,message='',target='#ev-heading')=>{if(!live(el))return false;if(dirty.size){unsaved();return false;}const r=fn();if(!r?.ok){say(r?.error||'This change could not be kept.',true);return false;}redraw(message||r.attempt?.feedback||'',target);return true;};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(live(b))fn(b);}));
 on('[data-ev-more]',()=>{const panel=root.querySelector('.ev-exploration');panel?.scrollIntoView({block:'start'});panel?.querySelector('h2')?.focus();});
 on('[data-ev-create]',b=>act(b,()=>{const r=createEvidenceStory(state,{story:root.querySelector('[data-ev-story]').value,challenge:Number(root.querySelector('[data-ev-challenge]').value),reader:root.querySelector('[data-ev-reader]').value},o);if(r.ok&&location.hash.startsWith('#learn/english/'))history.replaceState(null,'','#learn/english/before');return r;},'Story visit created. Your earlier work is kept.'));
 on('[data-ev-remove-review]',b=>{if(!live(b)||dirty.size){say('Save your visible words before selecting a removal.',true);return;}const key=root.querySelector('[data-ev-remove-choice]').value,u=removableEvidenceStories(state).find(u=>u.id===key),box=root.querySelector('[data-ev-remove-warning]');if(!u){say('Choose a generated story copy first.',true);return;}const w=state.evidenceVoice.units[key];box.innerHTML=`<p tabindex="-1" data-ev-remove-description>Remove ${esc(u.title)} · ${esc(key)}? This removes ${Object.values(w.drafts).filter(x=>x!=='').length} working writing fields, ${w.annotations.length} annotations, ${w.responses.length} attempts and ${['firstDraft','firstRevision','kept'].filter(k=>w[k]).length} kept draft/revision records, including all original and latest kept writing in this copy. Download notes first if you want to keep them.</p>${btn('data-ev-remove-confirm','Confirm removal of this copy')}${btn('data-ev-remove-cancel','Keep this copy')}`;box.querySelector('[data-ev-remove-description]').focus();box.querySelector('[data-ev-remove-confirm]').addEventListener('click',e=>act(e.currentTarget,()=>removeEvidenceStory(state,key,true,o),'Selected story copy removed. Other work is unchanged.'));box.querySelector('[data-ev-remove-cancel]').addEventListener('click',e=>{if(live(e.currentTarget)){box.replaceChildren();b.focus();}});});
 on('[data-ev-open]',b=>act(b,()=>{const r=startEvidenceVoice(state,b.dataset.evUnit,{...o,lesson:b.dataset.evOpen});if(r.ok&&location.hash.startsWith('#learn/english/'))history.replaceState(null,'',`#learn/english/${b.dataset.evOpen}`);return r;},'Lesson opened. Choose any help.'));
 on('[data-ev-unit-open]',b=>act(b,()=>{if(!b.dataset.evUnitOpen)return {ok:false,error:'Choose a saved story copy.'};const r=startEvidenceVoice(state,b.dataset.evUnitOpen,o);if(r.ok&&location.hash.startsWith('#learn/english/'))history.replaceState(null,'',`#learn/english/${evidenceVoiceView(state).work.lesson}`);return r;},'Saved story copy opened.'));
 on('[data-ev-support]',b=>act(b,()=>supportEvidence(state,b.dataset.evSupport,o),'Support recorded for this lesson.',`[data-ev-support="${b.dataset.evSupport}"]`));
 on('[data-ev-reading]',b=>act(b,()=>setEvidenceReading(state,b.dataset.evReading,o),'Reading report kept.',`[data-ev-reading="${b.dataset.evReading}"]`));
 on('[data-ev-answer]',b=>{const [q,c]=b.dataset.evAnswer.split(':');act(b,()=>answerEvidence(state,q,c,o),'',`#ev-feedback-${q}`);});
 on('[data-ev-skip]',b=>act(b,()=>skipEvidence(state,o),'Marked skipped. Every lesson is still open.','[data-ev-skip]'));
 on('[data-ev-keep]',b=>act(b,()=>keepEvidence(state,b.dataset.evKeep,o),'Version kept. Your first kept draft and first revision stay available.',`[data-ev-keep="${b.dataset.evKeep}"]`));
 root.querySelectorAll('[data-ev-field]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;const r=setEvidenceText(state,el.dataset.evField,el.value,o);if(r.ok){dirty.delete(el.dataset.evField);el.removeAttribute('aria-invalid');save?.();say('Words saved on this device.');}else{dirty.add(el.dataset.evField);el.setAttribute('aria-invalid','true');unsaved(r.error,false);}}));
 const noteDraft=()=>({anchor:root.querySelector('[data-ev-note-anchor]')?.value??'',kind:root.querySelector('[data-ev-note-kind]')?.value??'inference',text:root.querySelector('[data-ev-note-text]')?.value??''});
 let noteBase=noteDraft();const noteEdited=new Set();
 const saveNote=el=>{if(!live(el))return false;const visible=noteDraft(),field=el.hasAttribute('data-ev-note-text')?'text':el.hasAttribute('data-ev-note-anchor')?'anchor':'kind';noteEdited.add(field);for(const key of ['anchor','kind','text'])if(visible[key]!==noteBase[key])noteEdited.add(key);const previous=evidenceVoiceView(state).work?.annotationDraft??{anchor:'',kind:'inference',text:''},draft={...previous};for(const key of noteEdited)draft[key]=visible[key];const r=setEvidenceAnnotationDraft(state,draft,o);if(r.ok){noteBase=visible;noteEdited.clear();dirty.delete(annotationDirty);root.querySelectorAll('[data-ev-note-anchor],[data-ev-note-kind],[data-ev-note-text]').forEach(n=>n.removeAttribute('aria-invalid'));save?.();const w=evidenceVoiceView(state).work,p=w?.source.chapters.flatMap(c=>c.paragraphs).find(p=>p.id===draft.anchor);const preview=root.querySelector('.ev-note-preview');if(preview)preview.textContent=p?.text||'The chosen exact paragraph will appear here.';}else{dirty.add(annotationDirty);el.setAttribute('aria-invalid','true');if(dirty.size)unsaved(r.error,false);else say(r.error);}return r.ok;};
 root.querySelectorAll('[data-ev-note-anchor],[data-ev-note-kind],[data-ev-note-text]').forEach(el=>el.addEventListener(el.tagName==='TEXTAREA'?'input':'change',()=>saveNote(el)));
 on('[data-ev-anchor]',b=>{const select=root.querySelector('[data-ev-note-anchor]');if(!select){say('Open this lesson to keep a note on a passage.',true);return;}select.value=b.dataset.evAnchor;if(saveNote(select))select.focus();});
 on('[data-ev-note-keep]',b=>{const d=evidenceVoiceView(state).work?.annotationDraft??noteDraft();act(b,()=>annotateEvidence(state,d.anchor,d.kind,d.text,o),'Exact passage and annotation kept.','[data-ev-note-keep]');});
 root.querySelector('[data-ev-whole]')?.addEventListener('toggle',e=>{if(!e.target.open||!live(e.target)||!evidenceVoiceView(state).work)return;const ids=evidenceVoiceView(state).work.source.chapters.map(c=>c.id),r=exposeEvidence(state,ids,o);if(r.ok)save?.();else say(r.error);});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-ev-audio] [data-speak]');if(!b)return;if(!live(b)){e.stopImmediatePropagation();return;}if(!evidenceVoiceView(state).work)return;const r=supportEvidence(state,'audio',o);if(r.ok)save?.();else{e.stopImmediatePropagation();say(r.error);}},true);
 document.addEventListener('click',e=>{if(!dirty.size||!root.isConnected||root.contains(e.target))return;const control=e.target.closest('button,a,input,select,summary');if(control){e.preventDefault();e.stopImmediatePropagation();unsaved();}},{capture:true,signal:leaveGuard.signal});
 const pendingContext=()=>typeof notebook==='function'&&notebook()===state&&explorerId?.()===owner&&(!isActive||isActive())&&root.isConnected&&document.querySelector('[data-ev-root]')===root&&dirty.size>0;
 pendingEvidenceNavigation=()=>{if(!pendingContext())return false;history.replaceState(null,'',route);unsaved(undefined,false);return true;};
 window.addEventListener('beforeunload',e=>{if(pendingContext()){e.preventDefault();e.returnValue='';}},{signal:leaveGuard.signal});
 root.querySelectorAll('a').forEach(a=>a.addEventListener('click',e=>{if(!live(a)){e.preventDefault();e.stopPropagation();return;}if(dirty.size){e.preventDefault();e.stopPropagation();unsaved();}}));
}

function bindThreadsParent(book,ctx,root,{owner,route,dirty,unsaved}){
 const token={};threadParentBinding=token;const returning=returnView(book,owner);
 const chain=n=>{const a=[];for(let p=n;p;p=p.parentNode)a.push(p);return a;},rootChain=chain(root);
 const same=(n,a)=>{const b=chain(n);return b.length===a.length&&b.every((p,i)=>p===a[i]);};
 const visible=n=>{for(let p=n;p;p=p.parentElement){if(p.hidden||p.inert||p.getAttribute('aria-hidden')==='true'||getComputedStyle(p).display==='none'||['hidden','collapse'].includes(getComputedStyle(p).visibility))return false;if(p.tagName==='DETAILS'&&!p.open&&p!==n&&!p.querySelector(':scope > summary')?.contains(n))return false;}return true;};
 const bytes=()=>{try{return JSON.stringify([book.threadReadings,book.chapterMaps]);}catch{return false;}},raw=bytes();
 const stop=()=>{stopSpeech();ctx.stopSpeech?.();ctx.stopSound?.();};
 const nodes=root.querySelectorAll('[data-ev-threads],[data-ev-chapter-map],[data-tt-return],[data-tt-return] > summary,[data-tt-return] a[href],[data-tt-return-hear]');
 const lost=new Set();let rootLost=false;
 const audit=records=>{for(const record of records)for(const removed of record.removedNodes){if(removed===root||removed.contains?.(root))rootLost=true;for(const n of nodes)if(removed===n||removed.contains?.(n))lost.add(n);}};
 const observer=new MutationObserver(audit);observer.observe(document.body,{childList:true,subtree:true});threadParentCleanup=()=>{observer.disconnect();threadParentCleanup=null;};
 for(const n of nodes){const parents=chain(n);
  const live=()=>{audit(observer.takeRecords());try{return threadParentBinding===token&&!rootLost&&!lost.has(n)&&!threadMode&&!chapterMode&&root.isConnected&&n.isConnected&&root.contains(n)&&document.querySelector('[data-ev-root]')===root&&same(root,rootChain)&&same(n,parents)&&visible(n)&&!n.matches(':disabled')&&typeof ctx.notebook==='function'&&ctx.notebook()===book&&typeof ctx.explorerId==='function'&&ctx.explorerId()===owner&&typeof ctx.isActive==='function'&&ctx.isActive()===true&&location.hash===route&&raw!==false&&bytes()===raw;}catch{return false;}};
  for(const type of ['click','change','input','toggle','keydown','focusin'])n.addEventListener(type,e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});
  if(n.matches('[data-ev-threads]'))n.addEventListener('click',()=>{if(!live())return;if(dirty.size){unsaved();return;}stop();chapterMode=null;threadMode={book,owner,parentRoute:route};history.replaceState(null,'','#learn/english');ctx.render?.();ctx.focus?.('#tt-heading');});
  if(n.matches('[data-ev-chapter-map]'))n.addEventListener('click',()=>{if(!live())return;if(dirty.size){unsaved();return;}stop();threadMode=null;chapterMode={book,owner,parentRoute:route};history.replaceState(null,'','#learn/english');ctx.render?.();ctx.focus?.('#cm-heading');});
  if(n.matches('[data-tt-return]'))n.addEventListener('toggle',()=>{if(live()){stop();returning.open=n.open;}});
  if(n.matches('[data-tt-return-hear]')){const payload=n.dataset.speak||'';n.addEventListener('click',()=>{if(!live())return;const panel=n.closest('[data-tt-return]');if(!panel?.open)return;stop();n.dataset.speak=payload;},{capture:true});}
  if(n.matches('a,summary'))n.addEventListener('click',()=>{if(live())stop();});
 }
}
